preConditionHook:
// NO CLIMAX BAR IN THE LAST climaxLookback BARS, either direction. Grimes states
// it as a BLOCK -- "do not enter pullbacks following potential climaxes"
// (G03-09), and ch6 blocks the simple Pullback template while allowing the
// complex one (G06-29) -- but the corpus states every "do not trade while X"
// claim in the PASSING sense and lets the per-placement NEGATE toggle give the
// block. PostGapFadeBlockWindow is the construction copied here, including the
// positive statement.
//
// THE WINDOW FORM CANNOT BE BUILT BY NEGATING ClimaxBar: a single placement of
// that rule fires on ONE bar, and negating it says only that THIS bar is not a
// climax. ConsecutiveClimaxBarCount is the COUNT form with a separation rule
// and is not this either.
//
// BOTH DIRECTIONS COUNT -- a buying climax and a selling climax are each a
// reason to stand aside -- so the sides are identical text, exactly as
// PostGapFadeBlockWindow's are.
//
// The climax test is ClimaxBar's, term for term: a trend bar (close beyond
// open) whose body is at least bodyFraction of its own range and whose range is
// at least climaxMultiple ATRs.
//
// ONE ATR VALUE FOR THE WHOLE WINDOW, read at the current bar, which is
// LargeBarCountInWindow's and ConsecutiveClimaxBarCount's arrangement: the
// counted condition is written as an explicit loop rather than CountIF exactly
// so the stateful WFSafe_ accumulator is NOT re-evaluated at each counted
// offset. Reading the accumulator's own history at an offset is unmeasured and
// is not asked for.
//
// ATR is MultiWalk's WFSafe_AvgTrueRange, a ROLLING accumulator and a DIFFERENT
// FUNCTION from the plain built-in: seeded with a full N-term sum on the study's
// first calculated bar and again whenever the length changes, thereafter
// advanced as TWO SEPARATE STATEMENTS -- EasyLanguage evaluates
// S[1] + in - out left to right, and folding it to S += in - out rounds
// differently and lands on the other side of a threshold (@OJ 2015-02-20).
// AtrProfitTarget is the reference implementation with the measurements. The
// accumulator stays in the hook, which the generator emits unconditionally:
// EasyLanguage does not short-circuit and/or, so a stateful call inside a
// condition would advance every bar in EL and only on some bars in C++.
//
// The loop runs WITHOUT a break and the flag is cleared rather than the scan
// abandoned -- EasyLanguage has no loop break, and Max Bars Back must cover the
// window on every bar regardless.
//
// SHIFT TEST: bodies, ranges and the ATR are all differences of prices.
//
// Scratch below is declared in localVariables, not at hook scope, so the hooks
// survive a double placement; every one is fully assigned each bar before it is
// read.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLength;
noClimax = true;
for (int kk = 0; kk <= (int)climaxLookback - 1; ++kk) {
    if (el_gt(close[kk], open[kk]) && el_ge(close[kk] - open[kk], bodyFraction * (high[kk] - low[kk])) && el_ge(high[kk] - low[kk], climaxMultiple * atrValue)) noClimax = false;
    if (el_lt(close[kk], open[kk]) && el_ge(open[kk] - close[kk], bodyFraction * (high[kk] - low[kk])) && el_ge(high[kk] - low[kk], climaxMultiple * atrValue)) noClimax = false;
}
